from playwright.sync_api import sync_playwright
from pathlib import Path
import base64, json
ROOT=Path(__file__).resolve().parents[2]; OUT=ROOT/'test-artifacts'; OUT.mkdir(exist_ok=True)
def b64(path): return base64.b64encode(Path(path).read_bytes()).decode()
scene=b64(ROOT/'assets/exports/scene_living/campus_living_composite.png')
cloud_far=b64(ROOT/'assets/exports/living-sprites/cloud_far_01.png')
cloud_mid=b64(ROOT/'assets/exports/living-sprites/cloud_mid_02.png')
cloud_near=b64(ROOT/'assets/exports/living-sprites/cloud_near_01.png')
html=f'''<!doctype html><html><head><meta charset="utf-8"><style>
*{{box-sizing:border-box}}html,body{{margin:0;width:100%;height:100%;overflow:hidden;font-family:Arial,sans-serif}}body{{background:#50a5d7}}.shell{{position:relative;width:100vw;height:100vh;border:5px solid #5c1016;overflow:hidden}}.scene{{position:absolute;inset:0;background:url(data:image/png;base64,{scene}) center/cover no-repeat;image-rendering:pixelated}}.cloud{{position:absolute;image-rendering:pixelated;opacity:.82}}.c1{{width:16%;left:9%;top:10%}}.c2{{width:23%;left:37%;top:14%;opacity:.72}}.c3{{width:28%;left:68%;top:8%;opacity:.88}}.top{{position:absolute;z-index:4;top:18px;left:28px;right:28px;display:flex;align-items:start;justify-content:space-between;color:#7b1113;text-shadow:1px 1px #fff9f1}}.brand{{display:flex;gap:12px;align-items:center}}.tree{{font-size:48px;color:#014421}}.brand strong{{display:block;font:900 30px monospace;letter-spacing:.09em}}.brand small{{display:block;color:#654c3d;font-weight:700}}.nav{{display:flex;gap:28px;background:rgba(255,249,241,.42);padding:12px 18px;border-bottom:3px solid rgba(123,17,19,.15)}}.nav b:first-child{{border-bottom:4px solid #7b1113;padding-bottom:10px}}.board{{position:absolute;z-index:5;right:2.4%;top:15%;width:23%;min-width:310px;background:#fff9f1;border:4px solid #7b1113;box-shadow:0 0 0 2px #fff1dd,7px 8px rgba(65,29,22,.35);padding:28px 20px 18px;color:#292725}}.board h2{{text-align:center;margin:0 0 30px;font:900 30px monospace;color:#7b1113;letter-spacing:.08em}}.task{{border:2px solid #d7c9bb;background:#fffdfa;padding:16px;margin:10px 0;display:grid;grid-template-columns:18px 1fr 26px;gap:11px;align-items:center}}.task.sel{{background:#fff0c9;border-color:#f3b61f;box-shadow:inset 5px 0 #f3b61f}}.task i{{width:14px;height:14px;border:2px solid #7b1113}}.task strong{{color:#7b1113;font-size:18px}}.task span{{display:block;margin-top:4px;color:#625b56}}.quick{{margin-top:22px;border-top:1px dashed #cdb6a5;padding-top:15px}}.quick div{{border:2px dashed #caa893;padding:12px;text-align:center;color:#7b1113;font-weight:800;margin-top:10px}}.focus{{margin-top:14px;background:#9b111e;color:#fff9f1;border:3px solid #f3b61f;box-shadow:0 0 0 2px #7b1113;padding:16px;text-align:center;font:900 18px monospace;letter-spacing:.12em}}.dock{{position:absolute;z-index:6;left:22px;right:22px;bottom:16px;height:105px;background:#fff9f1;border:4px solid #7b1113;box-shadow:0 0 0 2px #fff1dd,5px 6px rgba(65,29,22,.35);display:grid;grid-template-columns:25% 13% 16% 15% 1fr;color:#292725}}.dock>div{{padding:16px 18px;border-right:1px dashed #d6bcaa;display:flex;flex-direction:column;justify-content:center}}.dock small{{font:900 10px monospace;color:#625b56;letter-spacing:.1em}}.dock strong{{font:900 22px monospace;color:#7b1113;margin-top:5px}}.radio{{display:grid!important;grid-template-columns:64px 1fr;gap:14px}}.thumb{{background:#234a44;color:white;display:grid;place-items:center;font:900 26px monospace;border:3px solid #7b1113}}.current{{border-right:0!important}}.bar{{height:7px;background:#efd9c6;margin-top:9px}}.bar i{{display:block;width:58%;height:100%;background:#9b111e}}.dark .board,.dark .dock{{background:#241719;color:#fff9f1}}.dark .task{{background:#341d21;border-color:#6e3b42}}.dark .task strong,.dark .dock strong{{color:#fff9f1}}.dark .task span,.dark .dock small{{color:#c9bdb3}}
@media(max-width:850px){{.shell{{height:auto;min-height:100vh;overflow:auto;background:#fff9f1}}.scene{{position:relative;height:42vh;background-size:cover}}.top{{top:10px;left:12px;right:12px}}.brand strong{{font-size:20px}}.tree{{font-size:34px}}.brand small,.nav{{display:none}}.board{{position:relative;right:auto;top:auto;width:auto;min-width:0;margin:-1px 12px 132px}}.dock{{position:fixed;height:100px;left:6px;right:6px;bottom:6px;grid-template-columns:1fr 1fr 1fr}}.dock .radio,.dock .current{{display:none!important}}}}
</style></head><body><main class="shell"><div class="scene"></div><img class="cloud c1" src="data:image/png;base64,{cloud_far}"><img class="cloud c2" src="data:image/png;base64,{cloud_mid}"><img class="cloud c3" src="data:image/png;base64,{cloud_near}"><header class="top"><div class="brand"><div class="tree">♣</div><div><strong>ELBI STUDY</strong><small>quiet work, campus rhythm</small></div></div><nav class="nav"><b>Campus</b><b>Plan</b><b>Learn</b><b>Stats</b><b>Settings</b></nav></header><aside class="board"><h2>TODAY</h2><div class="task sel"><i></i><div><strong>MATH 28</strong><span>Problem Set 3</span></div><b>▤</b></div><div class="task"><i></i><div><strong>CMSC 12</strong><span>Review arrays</span></div><b>▤</b></div><div class="task"><i></i><div><strong>STAT 101</strong><span>Exercises 4–8</span></div><b>▤</b></div><div class="quick"><div>＋ Add task</div></div><div class="focus">START FOCUS</div></aside><footer class="dock"><div class="radio"><div class="thumb">♪</div><div><small>AMBIENT</small><strong style="font-size:17px">Rainy Elbi</strong></div></div><div><small>TODAY</small><strong>52m</strong></div><div><small>THIS WEEK</small><strong>3h 42m</strong></div><div><small>CONSISTENCY</small><strong>4 / 5</strong></div><div class="current"><small>CURRENT</small><strong style="font-size:16px">MATH 28 — Problem Set 3</strong><div class="bar"><i></i></div></div></footer></main></body></html>'''
report={'screenshots':[],'checks':{}}
def check(n,v): report['checks'][n]=bool(v); print(('PASS' if v else 'FAIL'),n)
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage'])
 for name,viewport,dark in [('living-home-1536',{'width':1536,'height':960},False),('living-home-1366',{'width':1366,'height':768},False),('living-home-dark',{'width':1536,'height':960},True),('living-home-mobile',{'width':390,'height':844},False)]:
  page=b.new_page(viewport=viewport); page.set_content(html); page.wait_for_timeout(100)
  if dark: page.locator('.shell').evaluate("e=>e.classList.add('dark')")
  path=OUT/f'{name}.png'; page.screenshot(path=str(path),full_page=name.endswith('mobile')); report['screenshots'].append(str(path.relative_to(ROOT)))
  check(name+' board visible',page.locator('.board').is_visible()); check(name+' scene visible',page.locator('.scene').is_visible()); page.close()
 b.close()
(OUT/'living-visual-report.json').write_text(json.dumps(report,indent=2))
if not all(report['checks'].values()): raise SystemExit(1)
